/**
 * A rich-text editor: a document, the commands of its extensions, its
 * layout, and what to paint, with no UI of its own.
 *
 * The iOS and Android `CanvistView`s drive one; other hosts (React Native,
 * Lynx, tests) can drive one directly. Every method is safe to call from
 * any thread, one call at a time; views call from the main thread.
 *
 * Text input methods address the document as one string of UTF-16 code
 * units: every text block in order, joined by line feeds, with inline
 * embeds as one code unit. That is what `UITextInput` and Android's
 * `InputConnection` expect.
 */
public protocol EditorProtocol: AnyObject, Sendable {
    
    /**
     * The text blocks with rows between `top` and `bottom`, in document
     * order. Blocks outside the viewport that were never laid out have
     * estimated bounds.
     */
    func blocks(top: Float, bottom: Float)  -> [BlockInfo]
    
    /**
     * The visual lines of text between `top` and `bottom`, in document
     * order, for reading line by line.
     */
    func lines(top: Float, bottom: Float)  -> [LineInfo]
    
    /**
     * The selection for the pasteboard, or `None` when nothing is selected.
     */
    func copy() throws  -> ClipboardContent?
    
    /**
     * Copy the selection and delete it.
     */
    func cut() throws  -> ClipboardContent?
    
    /**
     * Paste HTML over the selection; paste rules apply.
     * Excessive nesting returns a `parse` error without changing the document.
     */
    func pasteHtml(html: String) throws  -> Bool
    
    /**
     * Paste Markdown over the selection.
     * Excessive nesting returns a `parse` error without changing the document.
     */
    func pasteMarkdown(markdown: String) throws  -> Bool
    
    /**
     * Paste plain text over the selection: one paragraph per line, or
     * verbatim inside code.
     */
    func pasteText(text: String) throws  -> Bool
    
    /**
     * Toggle the checkbox of the task whose first line is at `(x, y)`, in
     * document coordinates, as a tap on a checkbox item does, keeping the
     * selection where it was. Returns whether there was a task there.
     */
    func toggleTaskAt(x: Float, y: Float) throws  -> Bool
    
    /**
     * Integrate a v1 Yjs update from another peer. Updates may arrive in
     * any order and more than once. Returns whether the document changed.
     */
    func applyUpdate(update: Data) throws  -> Bool
    
    /**
     * Everything a peer at v1 `state_vector` is missing, as one v1 update.
     */
    func encodeDiff(stateVector: Data) throws  -> Data
    
    /**
     * The whole shared state as one v1 update, to persist or to send to a
     * joining peer.
     */
    func encodeState() throws  -> Data
    
    /**
     * This editor's changes since the last call, as y-sync update messages
     * for every connection.
     */
    func flushSync() throws  -> [Data]
    
    /**
     * Whether the document is shared.
     */
    func isShared()  -> Bool
    
    /**
     * Replace the document with a shared one, joined from Yjs `state` (v1,
     * as `encode_state` or `Y.encodeStateAsUpdate` returns) as yrs client
     * `client_id`.
     */
    func join(state: Data, clientId: UInt64) throws 
    
    /**
     * Handle one binary y-sync message, as y-websocket frames them. Send
     * `reply` back on the connection it came from; a relaying peer also
     * sends `broadcast` to its other connections.
     */
    func receiveSync(message: Data) throws  -> SyncReply
    
    /**
     * Start sharing the document as yrs client `client_id`, unique among
     * peers: its content becomes the shared state others join from.
     */
    func share(clientId: UInt64) throws 
    
    /**
     * The v1 state vector, which a peer answers with what this one lacks.
     */
    func stateVector() throws  -> Data
    
    /**
     * The y-sync message that starts a connection: sync step 1, asking
     * the other side for what this editor lacks.
     */
    func syncStart() throws  -> Data
    
    /**
     * Drain the v1 updates this editor's own changes produced, to send to
     * every other peer.
     */
    func takeUpdates() throws  -> [Data]
    
    /**
     * Report what a speech source said about `segment`, numbered from 0 in
     * each dictation session. Provisional text (`is_final` false) replaces
     * whatever the segment showed; final text never changes again and is
     * inserted once every earlier segment is final. The first report
     * replaces a selection, as typing does. Returns whether the document or
     * the provisional text changed.
     */
    func dictate(segment: UInt32, text: String, isFinal: Bool) throws  -> Bool
    
    /**
     * The provisional text showing at the caret, if any, as it reads with
     * the spaces that join it to the text around it.
     */
