#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEditor: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Editor

    public static func lift(_ handle: UInt64) throws -> Editor {
        return Editor(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Editor) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Editor {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Editor, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEditor_lift(_ handle: UInt64) throws -> Editor {
    return try FfiConverterTypeEditor.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeEditor_lower(_ value: Editor) -> UInt64 {
    return FfiConverterTypeEditor.lower(value)
}






/**
 * Told after every call that changed the editor, once the editor is ready
 * for more calls: an observer may read from or call into the editor.
 *
 * The iOS and Android views observe their editor to repaint, so commands
 * an app runs from a toolbar show up without further work.
 */
public protocol EditorObserver: AnyObject, Sendable {
    
    /**
     * Something changed.
     */
    func changed(change: EditorChange) 
    
}
/**
 * Told after every call that changed the editor, once the editor is ready
 * for more calls: an observer may read from or call into the editor.
 *
 * The iOS and Android views observe their editor to repaint, so commands
 * an app runs from a toolbar show up without further work.
 */
open class EditorObserverImpl: EditorObserver, @unchecked Sendable {
    fileprivate let handle: UInt64

    /// Used to instantiate a [FFIObject] without an actual handle, for fakes in tests, mostly.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public struct NoHandle {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    required public init(unsafeFromHandle handle: UInt64) {
        self.handle = handle
    }

    // This constructor can be used to instantiate a fake object.
    // - Parameter noHandle: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    //
    // - Warning:
    //     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing handle the FFI lower functions will crash.
#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public init(noHandle: NoHandle) {
        self.handle = 0
    }

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
    public func uniffiCloneHandle() -> UInt64 {
        return try! rustCall { uniffi_canvist_ffi_fn_clone_editorobserver(self.handle, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        if handle == 0 {
            // Mock objects have handle=0 don't try to free them
            return
        }

        try! rustCall { uniffi_canvist_ffi_fn_free_editorobserver(handle, $0) }
    }

    

    
    /**
     * Something changed.
     */
open func changed(change: EditorChange)  {try! rustCall() {
        uniffiCallStatus in
    uniffi_canvist_ffi_fn_method_editorobserver_changed(
            self.uniffiCloneHandle(),
        FfiConverterTypeEditorChange_lower(change),uniffiCallStatus
    )
}
}
    

    
}



// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceEditorObserver {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceEditorObserver = UniffiVTableCallbackInterfaceEditorObserver(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeEditorObserver.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface EditorObserver: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeEditorObserver.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface EditorObserver: handle missing in uniffiClone")
            }
        },
        changed: { (
            uniffiHandle: UInt64,
            change: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeEditorObserver.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.changed(
                     change: try FfiConverterTypeEditorChange_lift(change)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
