        )
        
        case 3: return .error(code: try FfiConverterTypeDictationErrorCode.read(from: &buf), message: try FfiConverterString.read(from: &buf), fatal: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .done
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DictationEvent, into buf: inout [UInt8]) {
        switch value {
        
        
